(() => {
  const old = window.__rscan;
  if (old) { old.vids = []; old.killed = true; }
  const vids = Object.keys(window.__big.map).map(Number).sort((a, b) => a - b);
  window.__rscan2 = {
    done: false, catId: 5908, vids: vids, total: vids.length,
    idx: 0, tested: 0, ok: 0, throttled: 0, failed: [], must: (old && old.must ? old.must.slice() : []), notShow: [],
    started: Date.now(), conc: 8, rounds: 0
  };
  const S = window.__rscan2;
  (async () => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const one = async (vid) => {
      for (let a = 0; a < 6; a++) {
        try {
          const r = await fetch('/glide/v2/mms/query/rules/limit/new', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ cat_id: S.catId, goods_type: 1, goods_properties: [{ ref_pid: 310, vid: vid }] }) });
          const j = await r.json();
          if (j && j.success) return { must: j.result.is_must_fake_one_lose_ten === true, ns: j.result.is_not_show_fake_one_lose_ten === true };
          const code = j && (j.error_code || j.errorCode);
          if (code === 55555 || code === 40002 || code === '40002') { S.throttled++; await sleep(1000 * (a + 1)); continue; }
          return { other: code };
        } catch (e) { await sleep(600 * (a + 1)); }
      }
      return null;
    };
    const run = async (list) => {
      let i = 0;
      const worker = async () => {
        while (i < list.length) {
          const v = list[i++];
          const r = await one(v);
          S.tested++;
          if (r === null) S.failed.push(v);
          else { S.ok++; if (r.must) S.must.push(v); if (r.ns) S.notShow.push(v); }
        }
      };
      await Promise.all(Array.from({ length: S.conc }, worker));
    };
    await run(S.vids);
    while (S.failed.length && S.rounds < 5) {
      const retry = S.failed.splice(0);
      S.rounds++;
      await run(retry);
      await sleep(2000);
    }
    S.done = true; S.finishedAt = Date.now();
  })();
  return JSON.stringify({ msg: 'robust rule scan started', total: vids.length, seededMust: S.must.length, etaMinAt20rps: Math.round(vids.length / 20 / 60) });
})()
